AssistantMessageToolRequest(name='create', tool_call_id='function-call-623ba862-beaa-4815-897f-63c0d69d016d', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    let cartItemCount = 0;
    const cartBtn = document.getElementById('cart-btn');
    const cartCountDisplay = cartBtn.querySelector('.cart-count');
    const announcer = document.getElementById('announcer');
    const addToCartButtons = document.querySelectorAll('.add-to-cart');

    // Handle Skip to Main Content Link
    const mainContent = document.getElementById('main-content');
    const skipLink = document.querySelector('.skip-link');

    skipLink.addEventListener('click', (e) => {
        e.preventDefault();
        mainContent.focus();
        mainContent.scrollIntoView();
    });

    // Handle Add to Cart functionality
    addToCartButtons.forEach(button => {
        button.addEventListener('click', function() {
            // Increment cart
            cartItemCount++;

            // Update UI
            cartCountDisplay.textContent = cartItemCount;

            // Update aria-label for the cart button for screen readers
            const itemText = cartItemCount === 1 ? 'item' : 'items';
            cartBtn.setAttribute('aria-label', `Shopping Cart, ${cartItemCount} ${itemText}`);

            // Get product name for announcement
            const productCard = this.closest('.product-card');
            const productName = productCard.querySelector('.product-name').textContent;

            // Announce to screen readers using ARIA live region
            announcer.textContent = `${productName} added to cart. You now have ${cartItemCount} ${itemText} in your cart.`;

            // Visual feedback on button
            const originalText = this.textContent;
            this.textContent = 'Added!';
            this.style.backgroundColor = '#22c55e'; // Accessible green
            this.style.color = '#000000'; // High contrast text
            this.style.borderColor = '#22c55e';

            setTimeout(() => {
                this.textContent = originalText;
                this.style.backgroundColor = '';
                this.style.color = '';
                this.style.borderColor = '';
            }, 2000);
        });
    });
});
