    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .deal-banner {
        flex-direction: column;
    }

    .deal-image {
        min-height: 200px;
    }

    .footer-grid {
        grid-template-columns: 1fr;
