    font-size: clamp(2.5rem, 5vw, 4.5rem);
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    letter-spacing: -1px;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: var(--spacing-lg);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--bg-surface);
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid var(--border-color);
    transition: transform 0.3s ease;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-4px);
    border-color: #404040;
}

.product-image {
    aspect-ratio: 4/5;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-details {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-name {
    font-size: 1.1rem;
    font-weight: 500;
    margin-bottom: 4px;
}

.product-price {
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
}

.add-to-cart {
    margin-top: auto;
    background-color: transparent;
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    width: 100%;
}

.add-to-cart:hover {
    background-color: var(--bg-surface-hover);
    border-color: var(--text-secondary);
}

/* Deals Banner */
.deal-banner {
    display: flex;
    background-color: var(--bg-surface);
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--border-color);
}

.deal-image {
    flex: 1;
    min-height: 300px;
}

.deal-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.deal-content {
    flex: 1;
