    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
}

.deal-content h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-sm);
}

.deal-content p {
    color: var(--text-secondary);
    font-size: 1.1rem;
    margin-bottom: var(--spacing-lg);
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    aspect-ratio: 16/10;
}

.editorial-image {
    position: absolute;
    inset: 0;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    opacity: 0.7;
    transition: opacity 0.3s ease;
}

.editorial-card:hover .editorial-image img {
    opacity: 0.5;
}

.editorial-content {
    position: absolute;
    inset: 0;
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    background: linear-gradient(to top, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0) 100%);
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 8px;
}

.editorial-link {
    text-decoration: none;
}

.editorial-link::after {
    content: '';
    position: absolute;
    inset: 0;
}

.editorial-content p {
    color: var(--text-secondary);
}

